/**
 * `site/static/time.js` and `engine/window.js` against the reference engine.
 *
 * `fixtures/time_cases.json` is Python's answer for the cases where a naive
 * epoch implementation and `zoneinfo` disagree; it is regenerated by
 * `harness/make_time_fixtures.py`. The unit tests below cover the parts of
 * time.js that `expand_window` only reaches indirectly.
 */

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

import {
  atMinute,
  compareWall,
  dateKey,
  epochFromWall,
  formatWhen,
  parseRequestTime,
  wallFromEpoch,
  wallKey,
  weekdayOf,
} from "../static/time.js";
import { CalendarContext } from "../static/engine/calendar.js";
import { expandWindow, meterIsCharged, ruleIsActive } from "../static/engine/window.js";

const FIXTURE = JSON.parse(
  readFileSync(fileURLToPath(new URL("./fixtures/time_cases.json", import.meta.url)), "utf-8"),
);

/** The civil fields of a Python `datetime.isoformat()` string, offset ignored. */
function civilFromIso(text) {
  return {
    year: Number(text.slice(0, 4)),
    month: Number(text.slice(5, 7)),
    day: Number(text.slice(8, 10)),
    hour: Number(text.slice(11, 13)),
    minute: Number(text.slice(14, 16)),
    second: Number(text.slice(17, 19)),
  };
}

function wallFromIso(text, fold) {
  return { ...civilFromIso(text), fold };
}

/** A `Regulation.model_dump(mode="json")` as `model.js` spells it. */
function regulationFromJson(json) {
  return {
    action: json.action,
    permitted: json.permitted,
    vehicleClass: json.vehicle_class,
    exclusive: json.exclusive,
    days: json.days,
    timeFrom: json.time_from,
    timeTo: json.time_to,
    metered: json.metered,
    maxDurationMin: json.max_duration_min,
    flags: {
      streetCleaning: json.flags.street_cleaning,
      schoolDays: json.flags.school_days,
      exceptSunday: json.flags.except_sunday,
      includingSunday: json.flags.including_sunday,
      snowEmergency: json.flags.snow_emergency,
      holidayExempt: json.flags.holiday_exempt,
      temporary: json.flags.temporary,
      meta: json.flags.meta,
    },
    effectiveFrom: json.effective_from,
    effectiveTo: json.effective_to,
    arrow: json.arrow,
  };
}

function calendarFromJson(json) {
  return new CalendarContext({
    aspSuspensionDates: json.asp_suspension_dates,
    majorHolidayDates: json.major_holiday_dates,
    meterSuspendedDates: json.meter_suspended_dates,
    nonSchoolDates: json.non_school_dates,
    snowEmergency: json.snow_emergency,
    calendarMissing: json.calendar_missing,
  });
}

test("every fixture instant reads back as the wall clock Python produced", () => {
  for (const item of FIXTURE.wall_clocks) {
    const wall = wallFromEpoch(item.epoch_ms);
    assert.deepStrictEqual(wall, wallFromIso(item.iso, item.fold), item.iso);
    assert.strictEqual(weekdayOf(wall), item.weekday, item.iso);
  }
});

test("every fixture wall clock resolves back to the instant it came from", () => {
  for (const item of FIXTURE.wall_clocks) {
    assert.strictEqual(epochFromWall(wallFromIso(item.iso, item.fold)), item.epoch_ms, item.iso);
  }
});

test("parse_request_time keeps the instant an offset names", () => {
  for (const item of FIXTURE.wall_clocks) {
    const wall = parseRequestTime(item.iso);
    assert.strictEqual(epochFromWall(wall), item.epoch_ms, item.iso);
  }
});

test("expand_window reproduces the reference intervals", () => {
  for (const item of FIXTURE.windows) {
    const regulations = item.regulations.map(regulationFromJson);
    const calendar = calendarFromJson(item.calendar);
    const intervals = expandWindow(
      parseRequestTime(item.t1),
      parseRequestTime(item.t2),
      regulations,
    );

    assert.strictEqual(intervals.length, item.intervals.length, item.name);
    intervals.forEach((interval, index) => {
      const expected = item.intervals[index];
      const where = `${item.name} [${index}]`;
      assert.deepStrictEqual(
        interval.start,
        wallFromIso(expected.start, expected.start_fold),
        where,
      );
      assert.deepStrictEqual(interval.end, wallFromIso(expected.end, expected.end_fold), where);
      assert.strictEqual(interval.minutes, expected.minutes, where);
      assert.strictEqual(interval.weekday, expected.weekday, where);
      assert.strictEqual(interval.date, expected.date, where);
      assert.strictEqual(interval.startMinuteOfDay, expected.start_minute_of_day, where);
      assert.strictEqual(formatWhen(interval.start, interval.end), expected.when, where);
      assert.deepStrictEqual(
        regulations.map((reg) => ruleIsActive(reg, interval, calendar)),
        expected.rule_active,
        where,
      );
      assert.deepStrictEqual(
        regulations.map((reg) => meterIsCharged(reg, interval, calendar)),
        expected.meter_charged,
        where,
      );
    });
  }
});

test("a naive ISO string is read as a New York wall clock", () => {
  assert.deepStrictEqual(parseRequestTime("2026-09-15T09:30"), {
    year: 2026,
    month: 9,
    day: 15,
    hour: 9,
    minute: 30,
    second: 0,
    fold: 0,
  });
});

test("a Z suffix names an instant and is converted", () => {
  assert.deepStrictEqual(parseRequestTime("2026-09-15T13:30:00Z"), {
    year: 2026,
    month: 9,
    day: 15,
    hour: 9,
    minute: 30,
    second: 0,
    fold: 0,
  });
});

test("a date with no time is midnight", () => {
  assert.strictEqual(wallKey(parseRequestTime("2026-09-15")), "2026-09-15T00:00");
});

test("a string that is not a date-time is rejected", () => {
  for (const text of ["", "tomorrow", "2026-13-01T00:00", "2026-02-30T00:00", "09/15/2026"]) {
    assert.throws(() => parseRequestTime(text), /ISO 8601/, text);
  }
});

test("minute 1440 is the next day's midnight", () => {
  assert.strictEqual(wallKey(atMinute(2026, 9, 14, 1440)), "2026-09-15T00:00");
  assert.strictEqual(wallKey(atMinute(2026, 12, 31, 1440)), "2027-01-01T00:00");
});

test("adding minutes to midnight is wall-clock arithmetic across a spring forward", () => {
  // 02:30 does not exist on 2026-03-08, and zoneinfo resolves it with the
  // offset in force before the transition: 07:30 UTC, not 06:30.
  const missing = atMinute(2026, 3, 8, 150);
  assert.strictEqual(wallKey(missing), "2026-03-08T02:30");
  assert.strictEqual(epochFromWall(missing), Date.UTC(2026, 2, 8, 7, 30));
});

test("fold decides which of two identical wall clocks an instant is", () => {
  const first = { year: 2026, month: 11, day: 1, hour: 1, minute: 30, second: 0, fold: 0 };
  const second = { ...first, fold: 1 };
  assert.strictEqual(epochFromWall(first), Date.UTC(2026, 10, 1, 5, 30));
  assert.strictEqual(epochFromWall(second), Date.UTC(2026, 10, 1, 6, 30));
  // Python compares two aware datetimes in one zone by wall clock, so these
  // two are equal to it and `expand_window` keeps only the first.
  assert.strictEqual(compareWall(first, second), 0);
});

test("format_when writes English three-letter weekdays", () => {
  const start = parseRequestTime("2026-09-20T09:05");
  const end = parseRequestTime("2026-09-20T17:00");
  assert.strictEqual(formatWhen(start, end), "Sun 09:05-17:00");
  assert.strictEqual(dateKey(start), "2026-09-20");
});
